animation: color_and_scale_after_delay;

animation-iteration-count: 3;
animation-duration: 5s;
}
@keyframes color_and_scale_after_delay {
80% {
transform: scale(1);
background-color: red;
}
80.1% {
background-color: green;
transform: scale(0.5);
}
